        state
            .write_user_memory_for_asid(asid, 0x1_0000, &req_bytes)
            .expect("write req");
        let mut frame = TrapFrame::zeroed();
        frame.set_syscall_num(Syscall::RecvSharedV3 as usize);
        frame.set_arg(0, 0x1_0000);
        frame.set_arg(1, 80);
